package uz.mirix.tracelens.internal;
import java.util.Locale; import java.util.regex.Pattern;
public final class SqlSanitizer {private static final Pattern BLOCK_COMMENT=Pattern.compile("/\\*.*?\\*/",Pattern.DOTALL),LINE_COMMENT=Pattern.compile("--[^\\r\\n]*"),QUOTED_STRING=Pattern.compile("'(?:''|[^'])*'"),NUMBER=Pattern.compile("(?<![\\w])[-+]?\\d+(?:\\.\\d+)?(?![\\w])"),UUID=Pattern.compile("(?i)\\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\\b"),WHITESPACE=Pattern.compile("\\s+");private SqlSanitizer(){} public static String sanitize(String sql,int maxLength){if(sql==null||sql.isBlank())return "<unknown>";String v=BLOCK_COMMENT.matcher(sql).replaceAll(" ");v=LINE_COMMENT.matcher(v).replaceAll(" ");v=QUOTED_STRING.matcher(v).replaceAll("?");v=UUID.matcher(v).replaceAll("?");v=NUMBER.matcher(v).replaceAll("?");v=WHITESPACE.matcher(v).replaceAll(" ").trim();if(v.length()>maxLength)v=v.substring(0,Math.max(1,maxLength-1))+"…";return v;} public static String label(String sql,int maxLength){String s=sanitize(sql,maxLength);if(s.isBlank())return "SQL";String first=s.split(" ",2)[0].toUpperCase(Locale.ROOT);return "SQL "+first+": "+s;}}
